import itertools
def rides(w, x):
    n = len(w); best = [(n + 1, 0)] * (1 << n); best[0] = (1, 0)
    for m in range(1, 1 << n):
        for i in range(n):
            if m >> i & 1:
                r, last = best[m ^ (1 << i)]
                cand = (r, last + w[i]) if last + w[i] <= x else (r + 1, w[i])
                if cand < best[m]: best[m] = cand
    return best[-1][0]
def slow(w, x):
    n = len(w)
    for k in range(1, n + 1):
        for assign in itertools.product(range(k), repeat=n):
            if all(sum(w[i] for i in range(n) if assign[i] == g) <= x for g in range(k)): return k
result = slow((4, 8, 6, 1), 10)

